t = 0:0.002:1.5;
A = 4; 
f = 3; 
sigma = 1; 
U1 = 2.5; 
U2 = 1.5;
s = A * sin(2 * pi * f * t);
n = sigma * randn(size(t));
signal = s + n;
filtered_signal = signal;
filtered_signal(abs(filtered_signal) < U2) = 0;
selected_indices = signal > U1;
selected_samples = signal(selected_indices);
t_selected = t(selected_indices);
figure; %[output:4bff3baf]
subplot(2, 1, 1); %[output:4bff3baf]
plot(t, signal, 'k-'); %[output:4bff3baf]
hold on; %[output:4bff3baf]
plot(t, filtered_signal, 'b:'); %[output:4bff3baf]
yline(U1, 'm-'); %[output:4bff3baf]
yline(U2, 'r--'); %[output:4bff3baf]
grid on; %[output:4bff3baf]
title('Original and Filtered Signals'); %[output:4bff3baf]
xlabel('Time (s)'); %[output:4bff3baf]
ylabel('Voltage (V)'); %[output:4bff3baf]
xlim([0, 1.5]); %[output:4bff3baf]
ylim([min(signal)-1, max(signal)+1]); %[output:4bff3baf]
legend('Original Signal', 'Filtered Signal', 'Threshold U_1', 'Threshold U_2', 'Location', 'southeast'); %[output:4bff3baf]
hold off; %[output:4bff3baf]
subplot(2, 1, 2); %[output:4bff3baf]
stem(t_selected, selected_samples); %[output:4bff3baf]
hold on; %[output:4bff3baf]
max_voltage = max(signal);
min_voltage = min(signal);
plot(t(signal == max_voltage), max_voltage, 'ro', 'MarkerFaceColor', 'red'); %[output:4bff3baf]
p = plot(t(signal == min_voltage), min_voltage, 'gd'); %[output:4bff3baf]
p.MarkerFaceColor = '#069642'; %[output:4bff3baf]
grid on; %[output:4bff3baf]
title('Discrete Samples and Voltage Extrema'); %[output:4bff3baf]
xlabel('Time (s)'); %[output:4bff3baf]
ylabel('Voltage (V)'); %[output:4bff3baf]
xlim([0, 1.5]); %[output:4bff3baf]
ylim([min(signal)-1, max(signal)+1]); %[output:4bff3baf]
legend('Signal > U_1', 'Maximum Voltage', 'Minimum Voltage', 'Location', 'southeast'); %[output:4bff3baf]
hold off; %[output:4bff3baf]

